# /// script
# requires-python = ">=3.12"
# ///
"""Watch the Jev router log and one Claude session transcript; print one line per routing event."""

import json
import sys
import time
from pathlib import Path

LOG = Path.home() / ".config/jev-router/log.jsonl"
TRANSCRIPT = Path(sys.argv[1])


def follow(path: Path):
    handle = path.open()
    handle.seek(0, 2)
    while True:
        line = handle.readline()
        yield line if line.endswith("\n") else None
        if not line:
            time.sleep(0.5)


def log_event(line: str) -> str | None:
    e = json.loads(line)
    fields = [f"{k}={e[k]}" for k in ("harness", "outcome", "size", "confidence", "latency_ms", "cost") if k in e]
    return "ROUTER " + " ".join(fields)


def text_of(content) -> str:
    if isinstance(content, str):
        return content
    for block in content or []:
        if isinstance(block, dict) and block.get("type") == "text":
            return block.get("text", "")
    return ""


def transcript_event(line: str) -> str | None:
    e = json.loads(line)
    msg = e.get("message") or {}
    if e.get("type") == "user" and not e.get("isSidechain") and not e.get("isMeta"):
        content = msg.get("content")
        if isinstance(content, str) or (isinstance(content, list) and any(b.get("type") == "text" for b in content if isinstance(b, dict))):
            text = text_of(content).strip().replace("\n", " ")
            if text and not text.startswith("<task-notification>"):
                return f"TYPED {e.get('timestamp', '')[11:19]} {text[:70]!r}"
    if e.get("type") == "attachment":
        att = e.get("attachment") or {}
        blob = json.dumps(att)
        if "UserPromptSubmit" in blob and ("Jev" in blob or "jev-router" in blob):
            if "not routing" in blob:
                return "HOOK told session to keep the message"
            if "jev-router:" in blob:
                return "HOOK told session to hand off"
    if e.get("type") == "assistant":
        for block in msg.get("content") or []:
            if isinstance(block, dict) and block.get("type") == "tool_use" and block.get("name") in ("Agent", "Task"):
                inp = block.get("input") or {}
                return f"SPAWN {inp.get('subagent_type')} model={inp.get('model')} desc={inp.get('description')!r}"
    return None


def main() -> None:
    sources = [(follow(LOG), log_event), (follow(TRANSCRIPT), transcript_event)]
    while True:
        for gen, handler in sources:
            line = next(gen)
            if line:
                try:
                    out = handler(line)
                except Exception as exc:  # noqa: BLE001
                    out = f"WATCHER could not parse a line: {type(exc).__name__}"
                if out:
                    print(out, flush=True)


if __name__ == "__main__":
    main()

