# /// script
# requires-python = ">=3.12"
# ///
"""Tally origin / promptSource / isMeta / leading characters of user entries, to classify typed input."""

import json
from collections import Counter
from datetime import UTC, datetime, timedelta
from pathlib import Path

ROOT = Path.home() / ".claude" / "projects"
since = datetime.now(UTC) - timedelta(days=30)
tally: Counter = Counter()
for path in ROOT.glob("*/*.jsonl"):
    if datetime.fromtimestamp(path.stat().st_mtime, UTC) < since:
        continue
    for line in path.open():
        try:
            e = json.loads(line)
        except json.JSONDecodeError:
            continue
        if not isinstance(e, dict) or e.get("type") != "user" or e.get("isSidechain"):
            continue
        content = (e.get("message") or {}).get("content")
        if isinstance(content, list):
            if any(isinstance(b, dict) and b.get("type") == "tool_result" for b in content):
                continue
            content = " ".join(b.get("text", "") for b in content if isinstance(b, dict) and b.get("type") == "text")
        if not isinstance(content, str):
            continue
        start = content.strip()[:12].replace("\n", " ")
        if start and start[0].isalnum():
            start = "<text>"
        origin = e.get("origin")
        origin = json.dumps(origin)[:40] if origin is not None else "-"
        tally[(origin, str(e.get("promptSource")), bool(e.get("isMeta")), start)] += 1
for key, n in tally.most_common(40):
    print(n, key)

