// ---- cost model --------------------------------------------------------
const call = (p, ctx, add, out) => (ctx * p.read + add * p.write + out * p.out) / 1e6;
function keepCost(c, k, add, out) {
  let s = 0;
  for (let i = 0; i < k; i++) s += call(OPUS, c + i * add, add, out);
  return s;
}
function delegateCost(c, k, add, out, helper, extra) {
  const p = helper === "sonnet" ? SONNET : OPUS;
  const rounds = Math.max(1, Math.round(k * (helper === "sonnet" ? extra : 1)));
  let h = (HELPER_START * p.write + out * p.out) / 1e6;
  for (let i = 1; i < rounds; i++) h += call(p, HELPER_START + i * add, add, out);
  return call(OPUS, c, 200, BRIEF) + h + call(OPUS, c + 200 + BRIEF, ANSWER, RELAY);
}

