// ---- cost model --------------------------------------------------------
// Closed form of costs.py's keep_cost and delegate_cost for its `synthetic` job:
// `c` cached tokens at the start, then each of `k` steps writes `add` new tokens
// and produces `out`. The step's context is c + (i + 1) * add.
function keepCost(c, k, add, out) {
  const p = OPUS;
  return (k * c * p.read + p.read * add * k * (k - 1) / 2 + k * add * p.write + k * out * p.out) / 1e6;
}
function delegateCost(c, k, add, out, helper, scale) {
  const p = OPUS, h = helper === "sonnet" ? SONNET : OPUS;
  const s = helper === "sonnet" ? scale : 1;
  const brief = (c * p.read + add * p.write + BRIEF * p.out) / 1e6;
  const first = HELPER_START * h.write + out * h.out;
  const rest = (k - 1) * HELPER_START * h.read + h.read * add * (k - 1) * (k - 2) / 2
    + (k - 1) * add * h.write + (k - 1) * out * h.out;
  const relay = ((c + add + BRIEF) * p.read + ANSWER * p.write + RELAY * p.out) / 1e6;
  return brief + s * (first + rest) / 1e6 + relay;
}

