  const same = delegateCost(start, steps, 3000, 2000, "opus", 1.25);
  const sonnet = delegateCost(start, steps, 3000, 2000, "sonnet", 1.25);
  console.log(`start ${start} steps ${steps}: keep ${keep.toFixed(4)} same ${same.toFixed(4)} sonnet ${sonnet.toFixed(4)}`);
}

