// Break-even lines: every job length where the cheaper option flips. There can
// be two: with a Sonnet helper that needs many extra steps, delegating wins
// only between a lower and an upper length.
const lines = [];
for (let x = pad.l; x <= pad.l + g.pw; x += 3) {
  const c = cOf(g, x);
  let cheaper = delegateCost(c, 1, add, out, state.helper, extra) < keepCost(c, 1, add, out);
  let crossing = 0;
  for (let k = 2; k <= Y_MAX; k++) {
    const now = delegateCost(c, k, add, out, state.helper, extra) < keepCost(c, k, add, out);
    if (now !== cheaper) {
      (lines[crossing] ||= []).push([x, yOf(g, k - 0.5)]);
      crossing++;
      cheaper = now;
    }
  }
  for (let j = crossing; j < lines.length; j++) lines[j].push(null);
}
ctx.strokeStyle = css("--ink");
ctx.lineWidth = 2;
for (const line of lines) {
  ctx.beginPath();
  let pen = false;
  for (const point of line) {
    if (!point) { pen = false; continue; }
    if (pen) ctx.lineTo(point[0], point[1]); else { ctx.moveTo(point[0], point[1]); pen = true; }
  }
  ctx.stroke();
}

