// Where the cheaper option flips, per the page's own model: Astra's case (50k, 3k, 2k, Sonnet x1.6) and the defaults.
import { readFileSync } from "node:fs";

const page = readFileSync(new URL("./page.template.html", import.meta.url), "utf8");
const prices = page.match(/const OPUS = [^\n]+\n\s+const SONNET = [^\n]+\n\s+const HELPER_START = [^\n]+/)[0];
const model = page.slice(page.indexOf("function keepCost"), page.indexOf("const params"));
const { keepCost, delegateCost } = new Function(`${prices}\n${model}\nreturn { keepCost, delegateCost };`)();
for (const [c, scale] of [[50000, 1.6], [300000, 1.25], [1000000, 1.25]]) {
  const flips = [];
  let cheaper = delegateCost(c, 1, 3000, 2000, "sonnet", scale) < keepCost(c, 1, 3000, 2000);
  for (let k = 2; k <= 200; k++) {
    const now = delegateCost(c, k, 3000, 2000, "sonnet", scale) < keepCost(c, k, 3000, 2000);
    if (now !== cheaper) { flips.push(`${now ? "delegate" : "keep"} from ${k}`); cheaper = now; }
  }
  console.log(`${c} context, Sonnet x${scale}: ${flips.join(", ") || "no flip"}`);
}

